import AppKit

/// The Transcript tab's bar (road map "creator-jobs" TX2b, spec §11 TX-24…
/// TX-27): pinned above the text as the pane's ONE `makeHeader()` instance,
/// so the controller hosts it above the scroll view as it hosts the Clip
/// tab's `ClipHeaderBlock`, and it never scrolls.
///
/// Top down: Words from and Language (an `InspectorRowLabel` at
/// `InspectorMetrics.labelWidth`, then an `OptionPopupControl` spanning the
/// rest of the row); the status row, its sentence wrapping, with Stop at its
/// right while the tab's waiter reads or Read when stopped; then the notes —
/// the same-speech notes, at most three "clip N — reason" rows and
/// "…and N more clips with no words.", whose tooltip lists the rest. What is
/// empty collapses. Every value is the source's (`TranscriptTabSource`); the
/// bar stores none, and rebuilds a popup only when its titles change.
final class TranscriptBar: NSView, OptionControl {
    /// The no-words rows shown before "…and N more".
    static let noWordsShown = 3

    private weak var source: TranscriptTabSource?
    private let stack = NSStackView()
    private let wordsSlot = NSView()
    private let languageSlot = NSView()
    private let statusRow = NSStackView()
    private let statusLabel: InspectorNoteLabel
    private let status: Lines
    private var stopButton: OptionButtonControl!
    private var readButton: OptionButtonControl!
    private let notes = NSStackView()
    private var noteTexts: [String] = []
    private var wordsTitles: [String] = []
    private var languageTitles: [String] = []
    private var wordsPopup: OptionPopupControl?
    private var languagePopup: OptionPopupControl?
    /// The popups a rebuild replaced, held a generation: a pick lands inside
    /// the old popup's own menu callback.
    private var retired: [NSView] = []

    init(source: TranscriptTabSource) {
        self.source = source
        let status = Lines()
        self.status = status
        statusLabel = InspectorNoteLabel(wraps: true) {
            status.lines.isEmpty ? nil : status.lines.joined(separator: "\n")
        }
        super.init(frame: .zero)
        stopButton = OptionButtonControl(
            title: "Stop", action: { [weak self] in self?.pressStop() }, enabled: { true }, onEdit: {})
        stopButton.setAccessibilityIdentifier("transcript.stop")
        stopButton.toolTip = "Stop reading on this Mac. A tool call's reading goes on."
        readButton = OptionButtonControl(
            title: "Read", action: { [weak self] in self?.pressRead() }, enabled: { true }, onEdit: {})
        readButton.setAccessibilityIdentifier("transcript.read")
        readButton.toolTip = "Read the files left on this Mac."

        stack.orientation = .vertical
        stack.alignment = .leading
        stack.spacing = InspectorMetrics.rowSpacing
        stack.edgeInsets = NSEdgeInsets(
            top: 8, left: InspectorMetrics.inset, bottom: 6, right: InspectorMetrics.inset)
        stack.translatesAutoresizingMaskIntoConstraints = false
        addSubview(stack)
        NSLayoutConstraint.activate([
            stack.topAnchor.constraint(equalTo: topAnchor),
            stack.leadingAnchor.constraint(equalTo: leadingAnchor),
            stack.trailingAnchor.constraint(equalTo: trailingAnchor),
            stack.bottomAnchor.constraint(equalTo: bottomAnchor),
        ])

        statusRow.orientation = .horizontal
        statusRow.alignment = .top
        statusRow.spacing = 8
        statusRow.distribution = .fill
        statusRow.addArrangedSubview(statusLabel)
        statusRow.addArrangedSubview(stopButton)
        statusRow.addArrangedSubview(readButton)
        // The sentence takes the row; the button keeps its own width.
        statusLabel.setContentHuggingPriority(NSLayoutConstraint.Priority(1), for: .horizontal)
        for button in [stopButton!, readButton!] {
            button.setContentHuggingPriority(.required, for: .horizontal)
            button.setContentCompressionResistancePriority(.required, for: .horizontal)
        }
        notes.orientation = .vertical
        notes.alignment = .leading
        notes.spacing = 4

        let rows: [NSView] = [
            row("Words from", wordsSlot), row("Language", languageSlot), statusRow, notes,
        ]
        for view in rows {
            stack.addArrangedSubview(view)
            view.widthAnchor.constraint(
                equalTo: stack.widthAnchor, constant: -2 * InspectorMetrics.inset
            ).isActive = true
        }
        refresh()
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("TranscriptBar does not support NSCoder")
    }

    override var isFlipped: Bool { true }

    /// The status sentences the status label reads.
    private final class Lines {
        var lines: [String] = []
    }

    /// A label at `labelWidth`, then `slot` to the row's end.
    private func row(_ title: String, _ slot: NSView) -> NSView {
        let box = NSView()
        let label = InspectorRowLabel(title)
        for view in [label, slot] {
            view.translatesAutoresizingMaskIntoConstraints = false
            box.addSubview(view)
        }
        NSLayoutConstraint.activate([
            label.leadingAnchor.constraint(equalTo: box.leadingAnchor),
            label.widthAnchor.constraint(equalToConstant: InspectorMetrics.labelWidth),
            label.centerYAnchor.constraint(equalTo: box.centerYAnchor),
            slot.leadingAnchor.constraint(equalTo: label.trailingAnchor, constant: 6),
            slot.trailingAnchor.constraint(equalTo: box.trailingAnchor),
            slot.topAnchor.constraint(equalTo: box.topAnchor),
            slot.bottomAnchor.constraint(equalTo: box.bottomAnchor),
            slot.heightAnchor.constraint(equalToConstant: DS.controlHeight),
        ])
        return box
    }

    /// `popup` in `slot`, spanning it.
    private func install(_ popup: OptionPopupControl, in slot: NSView) {
        let old = slot.subviews
        retired += old
        for view in old { view.removeFromSuperview() }
        popup.translatesAutoresizingMaskIntoConstraints = false
        popup.setContentHuggingPriority(.defaultLow, for: .horizontal)
        popup.setContentCompressionResistancePriority(.defaultLow, for: .horizontal)
        slot.addSubview(popup)
        NSLayoutConstraint.activate([
            popup.leadingAnchor.constraint(equalTo: slot.leadingAnchor),
            popup.trailingAnchor.constraint(equalTo: slot.trailingAnchor),
            popup.topAnchor.constraint(equalTo: slot.topAnchor),
            popup.bottomAnchor.constraint(equalTo: slot.bottomAnchor),
        ])
    }

    // MARK: - Refresh

    func refresh() {
        guard let source else { return }
        retired = []
        var moved = refreshPopups(source)
        status.lines = Self.statusText(source.status) ?? []
        statusLabel.refresh()
        let before = [stopButton.isHidden, readButton.isHidden, statusRow.isHidden]
        stopButton.isHidden = !stopShown
        readButton.isHidden = !readShown
        statusRow.isHidden = status.lines.isEmpty && !stopShown && !readShown
        moved = moved || before != [stopButton.isHidden, readButton.isHidden, statusRow.isHidden]
        moved = refreshNotes(source) || moved
        // A view coming or going lands at a zero frame until the next layout
        // pass: lay the window out now, so nothing reads it before then.
        if moved { window?.contentView?.layoutSubtreeIfNeeded() }
    }

    /// Rebuilds a popup whose titles changed, which it answers.
    private func refreshPopups(_ source: TranscriptTabSource) -> Bool {
        var rebuilt = false
        let trackChoices: [(title: String, value: UInt32?)] =
            [("All tracks", nil)] + source.tracks.map { ($0.name, Optional($0.id)) }
        let titles = trackChoices.map(\.title)
        if titles != wordsTitles || wordsPopup == nil {
            wordsTitles = titles
            let popup = OptionPopupControl(
                width: InspectorMetrics.popupWidth, choices: trackChoices,
                read: { [weak source] in source?.wordsFrom },
                write: { [weak self] in self?.chooseWordsFrom($0) },
                enabled: { true }, onEdit: {})
            popup.setAccessibilityIdentifier("transcript.words-from")
            wordsPopup = popup
            install(popup, in: wordsSlot)
            rebuilt = true
        } else {
            wordsPopup?.refresh()
        }

        let installed = source.languages ?? []
        // The default's identifier, not its name: "Automatic (English (United
        // States))" runs past the popup's chevron at the inspector's 280 pt.
        let automatic = Transcriber.defaultLanguage(in: installed).map {
            "Automatic (\($0.identifier))"
        } ?? "Automatic"
        let languageChoices: [(title: String, value: String?)] =
            [(automatic, nil)] + installed.map { ($0.displayName, Optional($0.identifier)) }
        let names = languageChoices.map(\.title)
        if names != languageTitles || languagePopup == nil {
            languageTitles = names
            let popup = OptionPopupControl(
                width: InspectorMetrics.popupWidth, choices: languageChoices,
                read: { [weak source] in source?.language },
                write: { [weak self] in self?.chooseLanguage($0) },
                enabled: { [weak source] in !(source?.languages ?? []).isEmpty }, onEdit: {})
            popup.setAccessibilityIdentifier("transcript.language")
            languagePopup = popup
            install(popup, in: languageSlot)
            rebuilt = true
        } else {
            languagePopup?.refresh()
        }
        return rebuilt
    }

    /// The same-speech notes, then at most `noWordsShown` clips with no
    /// words and one line for the rest; rebuilt only when the text changes,
    /// which it answers.
    private func refreshNotes(_ source: TranscriptTabSource) -> Bool {
        let rows = source.noWords.map { "\($0.tag) — \($0.reason)" }
        var texts = source.notes + rows.prefix(Self.noWordsShown)
        let rest = Array(rows.dropFirst(Self.noWordsShown))
        if !rest.isEmpty {
            texts.append("…and \(rest.count) more clip\(rest.count == 1 ? "" : "s") with no words.")
        }
        let hidden = notes.isHidden
        notes.isHidden = texts.isEmpty
        guard texts != noteTexts else { return hidden != notes.isHidden }
        noteTexts = texts
        for view in notes.arrangedSubviews { view.removeFromSuperview() }
        for (index, text) in texts.enumerated() {
            let label = InspectorNoteLabel(wraps: true) { text }
            if !rest.isEmpty, index == texts.count - 1 {
                label.toolTip = rest.joined(separator: "\n")
            }
            notes.addArrangedSubview(label)
            label.widthAnchor.constraint(equalTo: notes.widthAnchor).isActive = true
        }
        return true
    }

    /// The status line's sentences (TX-22, TX-26); nil when it says nothing.
    static func statusText(_ status: TranscriptTabSource.Status) -> [String]? {
        switch status {
        case .idle, .loading:
            return nil
        case .reading(let name, let fraction, let index, let of):
            return ["Reading “\(name)” on this Mac… \(Int((fraction * 100).rounded(.down))) % (\(index) of \(of))"]
        case .noModel:
            return [
                "This Mac has no speech model installed. Choose File ▸ Generate Captions…, pick "
                    + "a language and press Download."
            ]
        case .failed(let sentences):
            return sentences
        case .stopped(let remaining):
            return ["Stopped. \(remaining) file\(remaining == 1 ? "" : "s") not read on this Mac."]
        }
    }

    // MARK: - The controls' own paths (the dev tool presses these too)

    var stopShown: Bool { source?.canStop ?? false }

    var readShown: Bool {
        if case .stopped = source?.status { return true }
        return false
    }

    func chooseWordsFrom(_ track: UInt32?) {
        source?.setWordsFrom(track)
        refresh()
    }

    func chooseLanguage(_ identifier: String?) {
        source?.setLanguage(identifier)
        refresh()
    }

    func pressStop() {
        guard stopShown else { return }
        source?.stop()
        refresh()
    }

    func pressRead() {
        guard readShown else { return }
        source?.resume()
        refresh()
    }
}

import Foundation

/// What the Transcript tab shows, and its fill (road map "creator-jobs" TX2a,
/// spec §11 TX-22): the edited container's words as `TranscriptTokens`, the
/// clips with no words, the notes and the status line, rebuilt from a
/// per-media words cache, with this Mac's misses read by the tab's ONE
/// `TranscriptFill` owner (TX-12).
///
/// Main thread, but for two serial `.utility` queues of its own: the LOAD
/// queue reads a media's cloud transcript (TR-11), else its stored run, then
/// its pause set; the WAIT queue runs the one waiter, which wants the first
/// pending miss, waits for it and moves on — never the load queue, so a load
/// never waits behind a fill. Each media's words show as soon as its run is
/// stored, not when the last one ends.
///
/// `pending` (the misses in the fill's order, the media under the playhead
/// first) and the waiter's state are guarded by `lock`; `update()` replaces
/// `pending`, and releases the want when the media the waiter waits on is no
/// longer needed, which `wait` answers as `.cancelled`.
///
/// The bar's view state (TX2b, spec §11 TX-25, TX-26) is here too: Words from
/// (one track, or all), Language (an installed one, or the Mac's default),
/// and Stop, which withdraws only the tab's want, and Read.
///
/// Since TX3a (spec §11 TX-30) each media's voice cache is kept beside its
/// pause set, every read word (`allWords`, before Words from) beside the
/// model, and `cutTable()` is the cut's table, made once per rebuild.
///
/// Since TX1b (TX-18) a voice or peaks cache landing re-reads that `.apple`
/// media's words (`reloadDeviceWords`), kept shown until it merges; a load
/// that read before a landing (its epoch moved) is read again, not merged.
final class TranscriptTabSource {
    enum Status: Equatable {
        case idle, loading, reading(name: String, fraction: Double, index: Int, of: Int), noModel
        case failed([String])
        case stopped(remaining: Int)
    }

    private weak var document: ProjectDocument?
    private let onChange: () -> Void
    private(set) var model = TranscriptTokens.empty
    private(set) var noWords: [TimelineTranscript.NoWords] = []
    private(set) var notes: [String] = []
    private(set) var status: Status = .idle
    private(set) var rebuilds = 0
    /// Every read word of the edited container, before Words from (TX-32).
    private(set) var allWords: [TimelineTranscript.Word] = []
    private(set) var lastRebuildMilliseconds: Double = 0

    /// Words from: nil is All tracks (TX-25).
    private(set) var wordsFrom: UInt32?
    /// Language: a BCP-47 identifier; nil is Automatic, the Mac's default.
    private(set) var language: String?
    /// The edited container's tracks, from the last read, in snapshot order.
    private(set) var tracks: [TrackSnapshot] = []
    /// The installed languages; nil until read off main.
    private(set) var languages: [Transcriber.Language]?
    /// Stop was pressed and neither Read nor a show has come since (TX-26).
    private(set) var stopped = false

    /// Whether Stop applies: the tab's waiter reads on this Mac.
    var canStop: Bool {
        if case .reading = status { return true }
        return false
    }

    /// Whether the tab's owner wants a media of the fill now.
    var ownsWant: Bool {
        lock.lock()
        defer { lock.unlock() }
        return wanting
    }

    /// No load in flight, no waiter running, nothing pending.
    var settled: Bool {
        lock.lock()
        defer { lock.unlock() }
        return inFlight == 0 && !waiterRunning && pending.isEmpty && waiting.isEmpty
    }

    // Main only.
    private var shown = false
    private var read: TimelineTranscript.DocumentRead?
    private var words: [UInt32: TimelineTranscript.MediaWords] = [:]
    private var pauseSets: [UInt32: Set<Ticks>] = [:]
    private var speech: [UInt32: [Float]] = [:]
    private var table: TranscriptCut.Table?
    private var missItems: [UInt32: TranscriptFill.Item] = [:]
    private var failures: [UInt32: String] = [:]
    private var loading: Set<UInt32> = []
    private var noModel = false
    private var dirty = false
    private var poll: Timer?
    /// Each `.apple` media's item, and the media with a re-read in flight (TX-18).
    private var deviceItems: [UInt32: TranscriptFill.Item] = [:]
    private var rereading: Set<UInt32> = []

    private let fill: TranscriptFill
    private let owner: Int
    private let loadQueue = DispatchQueue(
        label: "com.kgalligan.framejob.transcript-tab-load", qos: .utility)
    private let waitQueue = DispatchQueue(
        label: "com.kgalligan.framejob.transcript-tab-wait", qos: .utility)

    // Guarded by `lock`.
    private let lock = NSLock()
    private var pending: [TranscriptFill.Item] = []
    private var pendingTotal = 0
    private var waiting: [TranscriptFill.Item] = []
    private var waiterRunning = false
    private var wanting = false
    private var inFlight = 0
    private var generation = 0
    /// Bumped by each voice or peaks cache landing for a media (TX-18).
    private var epochs: [UInt32: Int] = [:]

    /// Main. A pane is only made for an inspector that has its document;
    /// without one the source answers nothing and its fill is never used.
    init(document: ProjectDocument?, onChange: @escaping () -> Void) {
        self.document = document
        self.onChange = onChange
        fill = document.map { TranscriptFill.fill(for: $0) } ?? TranscriptFill(key: Int.min)
        owner = fill.newOwner()
    }

    deinit {
        poll?.invalidate()
        fill.release(owner: owner)
    }

    /// Shown: load and want. Hidden: release the want, stop the poll, drop
    /// the words cache.
    func setShown(_ shown: Bool) {
        guard shown != self.shown else { return }
        self.shown = shown
        if shown {
            failures = [:]
            noModel = false
            stopped = false
            loadLanguages()
            update()
            poll = Timer.scheduledTimer(withTimeInterval: 0.25, repeats: true) { [weak self] _ in
                self?.polled()
            }
            return
        }
        poll?.invalidate()
        poll = nil
        lock.lock()
        generation += 1
        pending = []
        pendingTotal = 0
        waiting = []  // so a show before the waiter wakes pends its media again
        wanting = false
        fill.release(owner: owner)
        lock.unlock()
        words = [:]
        pauseSets = [:]
        speech = [:]
        deviceItems = [:]
        rereading = []  // a re-read in flight is dropped by the generation; the next show loads it
        missItems = [:]
        loading = []
        status = .idle
    }

    /// A new edited project: re-read the instances, rebuild from the cached
    /// words, and load the misses. Never while a live gesture runs; the next
    /// call after it rebuilds.
    func update() {
        guard shown, let document else { return }
        if document.isLiveEditing {
            dirty = true
            return
        }
        dirty = false
        let started = DispatchTime.now().uptimeNanoseconds
        read = TimelineTranscript.read(document: document)
        tracks = read?.snapshot.tracks ?? []
        if let chosen = wordsFrom, !tracks.contains(where: { $0.id == chosen }) { wordsFrom = nil }
        rebuild(started: started)
        refreshPending()
        loadMisses()
    }

    /// Whether a rebuild was put off by a live gesture.
    var isDirty: Bool { dirty }

    // MARK: - The bar's choices (TX-25, TX-26)

    /// Words from: one track of the edited container, or nil for all.
    func setWordsFrom(_ track: UInt32?) {
        guard track != wordsFrom else { return }
        wordsFrom = track
        update()
    }

    /// Language: drops this Mac's words, their misses and failures, and the
    /// waiter's want, as a hide does, then reads again in the new language.
    func setLanguage(_ identifier: String?) {
        guard identifier != language else { return }
        language = identifier
        lock.lock()
        generation += 1
        pending = []
        pendingTotal = 0
        waiting = []
        wanting = false
        fill.release(owner: owner)
        lock.unlock()
        for (media, heard) in words where heard.engine == .apple {
            words[media] = nil
            pauseSets[media] = nil
            speech[media] = nil
            deviceItems[media] = nil
        }
        rereading = []  // as `hide`: the new generation's `loadMisses` must not skip them
        missItems = [:]
        failures = [:]
        loading = []
        noModel = false
        update()
    }

    /// Stop: the tab's want only, the waiter's queue emptied first, so a
    /// tool call's run of the same media goes on (TX-26).
    func stop() {
        guard shown else { return }
        stopped = true
        lock.lock()
        pending = []
        pendingTotal = 0
        waiting = []  // so a Read before the waiter wakes pends its media again
        wanting = false
        fill.release(owner: owner)  // Stop: the tab's want only (TX-26)
        lock.unlock()
        refreshPending()
        onChange()
    }

    /// Read: the misses wanted again.
    func resume() {
        guard stopped else { return }
        stopped = false
        update()
        onChange()
    }

    /// A voice or peaks cache of `media` landed (TX-18): its epoch moves, so
    /// a load that read before it is read again, and words already shown are
    /// re-read, kept on screen until that merges. Main.
    func reloadDeviceWords(media: UInt32) {
        lock.lock()
        epochs[media, default: 0] += 1
        lock.unlock()
        if let item = deviceItems[media] { reread(item) }
    }

    /// `media`'s epoch, read before its caches are.
    private func epoch(_ media: UInt32) -> Int {
        lock.lock()
        defer { lock.unlock() }
        return epochs[media, default: 0]
    }

    /// An `.apple` media's words and pause set, read at `epoch`, merged; or,
    /// when a cache landed since, read again instead. Main.
    private func mergeDevice(_ item: TranscriptFill.Item, _ read: Read, epoch: Int) -> Bool {
        guard epoch == self.epoch(item.media) else {
            reread(item)
            return false
        }
        words[item.media] = read.0
        pauseSets[item.media] = read.1.0
        speech[item.media] = read.1.1
        deviceItems[item.media] = item
        return true
    }

    /// One re-read of `item`, at most one in flight per media; the shown
    /// words stay until it merges (TX-18).
    private func reread(_ item: TranscriptFill.Item) {
        guard shown, rereading.insert(item.media).inserted else { return }
        loadStored(item)
    }

    /// The installed languages, read once per show on the load queue.
    private func loadLanguages() {
        lock.lock()
        inFlight += 1
        lock.unlock()
        loadQueue.async { [weak self] in
            let list = Transcriber.languages()
            DispatchQueue.main.async {
                guard let self else { return }
                self.end()
                self.languages = list
                self.onChange()
            }
        }
    }

    /// Words, pause sets and voice caches given whole, then `update()` — for
    /// the probes only.
    func preload(
        _ words: [UInt32: TimelineTranscript.MediaWords], pauses: [UInt32: Set<Ticks>],
        speech: [UInt32: [Float]] = [:]
    ) {
        self.words.merge(words) { _, new in new }
        pauseSets.merge(pauses) { _, new in new }
        self.speech.merge(speech) { _, new in new }
        update()
    }

    /// The cut's table over the last rebuild's words (TX-30), made once per rebuild. A media
    /// read before its voice cache landed has it read here (main; one small file), so the tab
    /// cuts as `get_timeline_transcript` answers.
    func cutTable() -> TranscriptCut.Table {
        if let table { return table }
        var context = speech
        if let cacheDir = read?.cacheDir {
            for media in words.keys where context[media] == nil {
                context[media] = MediaImporter.loadSpeech(for: media, in: cacheDir)
            }
        }
        speech = context
        let made = TranscriptCut.Table(
            all: allWords, tracks: wordsFrom.map { [$0] },
            context: TranscriptCut.Context(instances: read?.instances ?? [], media: words, speech: context))
        table = made
        return made
    }

    // MARK: - The model

    /// The media the shown words need; with a track chosen, only those with
    /// an instance on it (TX-25).
    private var needed: [UInt32] {
        guard let read else { return [] }
        let instances = read.instances.filter { wordsFrom == nil || $0.track == wordsFrom }
        return TimelineTranscript.neededMedia(instances, window: nil, playhead: read.playhead)
    }

    private func rebuild(started: UInt64 = DispatchTime.now().uptimeNanoseconds) {
        if document?.isLiveEditing == true {
            dirty = true
            return
        }
        if let read {
            let all = TimelineTranscript.words(read.instances, media: words, snapshot: read.snapshot)
            let shown = all.filter { wordsFrom == nil || $0.track == wordsFrom }
            model = TranscriptTokens.build(shown, pauses: pauseSets)
            allWords = all
            noWords = read.noWords
            notes = TimelineTranscript.sameSpeech(shown, instances: read.instances)
        } else {
            model = .empty
            allWords = []
            noWords = []
            notes = []
        }
        table = nil
        rebuilds += 1
        refreshStatus()
        onChange()
        lastRebuildMilliseconds = Double(DispatchTime.now().uptimeNanoseconds - started) / 1e6
    }

    // MARK: - Loads

    /// Reads each needed media with no words yet: its cloud transcript,
    /// else its stored run, else a fill item; then its pause set.
    private func loadMisses() {
        guard let read, let document else { return }
        let toLoad = needed.filter {
            words[$0] == nil && failures[$0] == nil && missItems[$0] == nil && !loading.contains($0)
                && !rereading.contains($0)
        }
        guard !toLoad.isEmpty else { return }
        let jobs = toLoad.compactMap { media -> (MediaSnapshot, URL)? in
            guard let record = read.records[media], let url = read.urls[media] else { return nil }
            return (record, url)
        }
        guard let cacheDir = read.cacheDir ?? document.cacheDirectory else {
            for media in toLoad { failures[media] = "The project has no cache folder to keep the words in." }
            refreshStatus()
            onChange()
            return
        }
        loading.formUnion(toLoad)
        let generation = begin()
        let wanted = self.language
        let epochs = Dictionary(uniqueKeysWithValues: toLoad.map { ($0, epoch($0)) })
        loadQueue.async { [weak self] in
            var found: [UInt32: Read] = [:]
            var items: [UInt32: TranscriptFill.Item] = [:]
            var missed: [UInt32: TranscriptFill.Item] = [:]
            var unreadable: [UInt32: String] = [:]
            var modelMissing = false
            var language: Transcriber.Language??
            for (record, url) in jobs {
                if let cloud = TimelineTranscript.cloudWords(record, url: url, cacheDir: cacheDir) {
                    found[record.id] = (cloud, Self.pauses(cloud, cacheDir: cacheDir))
                    continue
                }
                if language == nil { language = Self.resolve(wanted, in: Transcriber.languages()) }
                guard let chosen = language ?? nil else {
                    modelMissing = true
                    continue
                }
                guard
                    let item = TimelineTranscript.fillItem(
                        record, url: url, cacheDir: cacheDir, language: chosen)
                else {
                    unreadable[record.id] = "“\(record.name)” cannot be read."
                    continue
                }
                if let device = TimelineTranscript.deviceWords(item) {
                    found[record.id] = (device, Self.pauses(device, cacheDir: cacheDir))
                    items[record.id] = item
                } else {
                    missed[record.id] = item
                }
            }
            Self.holdLoad()
            DispatchQueue.main.async {
                guard let self else { return }
                self.end()
                self.loading.subtract(jobs.map(\.0.id))
                guard self.isCurrent(generation) else { return }
                for (media, pair) in found {
                    if let item = items[media] {
                        _ = self.mergeDevice(item, pair, epoch: epochs[media] ?? 0)
                        continue
                    }
                    self.words[media] = pair.0
                    self.pauseSets[media] = pair.1.0
                    self.speech[media] = pair.1.1
                }
                self.missItems.merge(missed) { _, new in new }
                self.failures.merge(unreadable) { _, new in new }
                self.noModel = self.noModel || modelMissing
                self.rebuild()
                self.refreshPending()
            }
        }
    }

    private func begin() -> Int {
        lock.lock()
        defer { lock.unlock() }
        inFlight += 1
        return generation
    }

    private func end() {
        lock.lock()
        inFlight -= 1
        lock.unlock()
    }

    private func isCurrent(_ generation: Int) -> Bool {
        lock.lock()
        defer { lock.unlock() }
        return shown && generation == self.generation
    }

    // MARK: - The fill, one media at a time

    /// The misses still needed, in the fill's order, as the new pending
    /// list; the want released when what the waiter waits on is not needed.
    private func refreshPending() {
        let order = needed
        let items = stopped ? [] : order.compactMap { media in
            words[media] == nil && failures[media] == nil ? missItems[media] : nil
        }
        lock.lock()
        let running = Set(waiting.map(\.media))
        if !waiting.isEmpty, !waiting.contains(where: { order.contains($0.media) }) {
            fill.release(owner: owner)
            wanting = false
        }
        pending = items.filter { !running.contains($0.media) }
        pendingTotal = items.count
        if !waiterRunning, !pending.isEmpty {
            waiterRunning = true
            waitQueue.async { [weak self] in self?.waitLoop() }
        }
        lock.unlock()
        refreshStatus()
    }

    /// The one waiter: wants the first pending media, waits until it
    /// settles, and moves on until nothing is pending.
    private func waitLoop() {
        while true {
            lock.lock()
            guard !pending.isEmpty else {
                waiterRunning = false
                if wanting {
                    fill.release(owner: owner)
                    wanting = false
                }
                lock.unlock()
                DispatchQueue.main.async { [weak self] in self?.polled() }
                return
            }
            let take = 1
            let batch = Array(pending.prefix(take))
            pending.removeFirst(batch.count)
            waiting = batch
            wanting = true
            fill.want(owner: owner, items: batch)
            let generation = self.generation
            lock.unlock()
            let outcomes = fill.wait(owner: owner)
            lock.lock()
            waiting = []
            let current = generation == self.generation
            lock.unlock()
            guard current else { continue }
            for item in batch {
                switch outcomes[item.media] ?? .cancelled {
                case .stored: loadStored(item, generation: generation)
                case .failed(let why):
                    DispatchQueue.main.async { [weak self] in
                        guard let self, self.isCurrent(generation) else { return }
                        self.failures[item.media] = why
                        self.refreshStatus()
                        self.onChange()
                    }
                case .cancelled: break
                }
            }
        }
    }

    /// A stored run's words and pause set, read on the load queue at its media's epoch, then
    /// merged and rebuilt on main; with no `generation`, `reread`'s, at the current one.
    private func loadStored(_ item: TranscriptFill.Item, generation: Int? = nil) {
        lock.lock()
        inFlight += 1
        let rereads = generation == nil
        let generation = generation ?? self.generation
        let epoch = epochs[item.media, default: 0]
        lock.unlock()
        loadQueue.async { [weak self] in
            let read = TimelineTranscript.deviceWords(item)
                .map { ($0, Self.pauses($0, cacheDir: item.cacheDir)) }
            Self.holdLoad()
            DispatchQueue.main.async {
                guard let self else { return }
                self.end()
                if rereads, self.isCurrent(generation) { self.rereading.remove(item.media) }  // else cleared
                guard self.isCurrent(generation), let read else { return }
                self.missItems[item.media] = nil
                if self.mergeDevice(item, read, epoch: epoch) { self.rebuild() }
            }
        }
    }

    // MARK: - Status

    private func polled() {
        let before = status
        refreshStatus()
        if status != before { onChange() }
    }

    private func refreshStatus() {
        lock.lock()
        let running = waiting.first
        let remaining = pending.count
        let total = pendingTotal
        lock.unlock()
        let unread = stopped ? needed.filter { words[$0] == nil && missItems[$0] != nil }.count : 0
        if let running {
            let progress = fill.progress()
            let fraction = progress?.media == running.media ? progress?.fraction ?? 0 : 0
            let of = max(total, 1)
            status = .reading(
                name: running.name, fraction: fraction, index: min(max(total - remaining, 1), of), of: of)
        } else if unread > 0 {
            status = .stopped(remaining: unread)
        } else if !failures.isEmpty {
            status = .failed(failures.keys.sorted().compactMap { failures[$0] })
        } else if noModel {
            status = .noModel
        } else if !loading.isEmpty {
            status = .loading
        } else {
            status = .idle
        }
    }

    /// The fill's running media and its fraction, for `transcript_view`.
    var fillProgress: (media: UInt32, fraction: Double)? { fill.progress() }
}
import Foundation

/// `TranscriptTabSource`'s two statics that hold no instance state, moved out
/// whole (a pure move, road map "creator-jobs" TX1b) so the source has room
/// under the ~600-line cap: the chosen language and a media's pause set.
extension TranscriptTabSource {

    /// One media's read: its words, and its pause set with the voice cache
    /// it was read from.
    typealias Read = (TimelineTranscript.MediaWords, (Set<Ticks>, [Float]?))

    /// The chosen language among `list`, else the Mac's default. Any thread.
    static func resolve(
        _ wanted: String?, in list: [Transcriber.Language]
    ) -> Transcriber.Language? {
        wanted.flatMap { Transcriber.language(matching: $0, in: list) }
            ?? Transcriber.defaultLanguage(in: list)
    }

    /// A media's pause set, and the voice cache it was read from (TX-30).
    static func pauses(
        _ words: TimelineTranscript.MediaWords, cacheDir: URL
    ) -> (Set<Ticks>, [Float]?) {
        let speech = MediaImporter.loadSpeech(for: words.media, in: cacheDir)
        return (
            TranscriptTokens.pauses(
                words.words, speech: speech,
                confidence: Float(SilenceDetector.Settings.defaultVoiceConfidence)), speech)
    }

    #if FRAMEJOB_DEV_TOOLS
    /// Probes only (TX1b's U10): each load block waits on it after its read,
    /// before its main hop.
    static var loadHold: DispatchSemaphore?
    #endif

    /// The probes' hold between a load's read and its main hop; nothing
    /// without `FRAMEJOB_DEV_TOOLS` or a hold set.
    static func holdLoad() {
        #if FRAMEJOB_DEV_TOOLS
        loadHold?.wait()
        #endif
    }
}

