396	/// `TranscriptView`'s keys and clicks (spec §11 TX-21). It takes ← and →
397	/// (one word, selected and sought, through `onActivate`), ↑ and ↓ (the word
398	/// nearest in x on the adjacent laid-out line, the same), ⇧ with any of them
399	/// (extend the selection, no seek), ⌘A (`selectAll(_:)`, which the nil-target
400	/// Edit ▸ Select All reaches first), Esc (clear the selection, or pass the key
401	/// up when there is none), and ⌫ and ⌦ with words selected (`deleteKey()`,
402	/// TX3a, spec §11 TX-31: one "Delete Words"; Edit ▸ Delete's bare ⌫ reaches
403	/// the editor's forward first). Since TX3b (TX-34) a click on a pause token
404	/// selects it; Esc, ⌫ and ⌦ act on it, and the arrows move from the word
405	/// before it. With nothing selected they pass up, and
406	/// Return passes up unchanged until TX5. Every other key goes to
407	/// `super.keyDown`, so J, K, L, I, O and M reach `handleEditorKey` as from the
408	/// timeline; Space never arrives here (`SpaceKey.route` takes it at the
409	/// window). A click makes the view first responder; a drag selects
410	/// (`+Delete`). Every selection a person makes is told through `onSelect`.
411	extension TranscriptView {
412	
413	    override func keyDown(with event: NSEvent) {
414	        let flags = event.modifierFlags.intersection([.command, .option, .control, .shift])
415	        guard let scalar = event.charactersIgnoringModifiers?.unicodeScalars.first?.value,
416	            flags.isSubset(of: [.shift])
417	        else {
418	            super.keyDown(with: event)
419	            return
420	        }
421	        let extend = flags.contains(.shift)
422	        let held = selection != nil || pauseSelection != nil
423	        switch scalar {
424	        case UInt32(NSLeftArrowFunctionKey): step(by: -1, extend: extend)
425	        case UInt32(NSRightArrowFunctionKey): step(by: 1, extend: extend)
426	        case UInt32(NSUpArrowFunctionKey): line(up: true, extend: extend)
427	        case UInt32(NSDownArrowFunctionKey): line(up: false, extend: extend)
428	        case 27 where !extend && held: select(nil)
429	        case 0x7F where !extend && held, UInt32(NSDeleteFunctionKey) where !extend && held:
430	            deleteKey()
431	        default: super.keyDown(with: event)
432	        }
433	    }
434	
435	    override func selectAll(_ sender: Any?) {
436	        guard !tokenStarts.isEmpty else { return }
437	        select(0...(tokenStarts.count - 1))
438	    }
439	
440	    /// The token a key moves from: the selection's moving end, else the
441	    /// word before a selected pause, else the highlighted word.
442	    private var caret: Int? {
443	        guard let selection else { return pauseSelection.map { pauses[$0].after } ?? highlighted }
444	        if let anchor = selectionAnchor, anchor == selection.upperBound, anchor != selection.lowerBound {
445	            return selection.lowerBound
446	        }
447	        return selection.upperBound
448	    }
449	
450	    private func step(by delta: Int, extend: Bool) {
451	        guard !tokenStarts.isEmpty else { return }
452	        let from = caret ?? (delta > 0 ? -1 : tokenStarts.count)
453	        move(to: min(max(from + delta, 0), tokenStarts.count - 1), extend: extend)
454	    }
455	
456	    private func line(up: Bool, extend: Bool) {
457	        guard let from = caret ?? (tokenStarts.isEmpty ? nil : 0),
458	            let target = tokenOnAdjacentLine(to: from, up: up)
459	        else {
460	            NSSound.beep()
461	            return
462	        }
463	        move(to: target, extend: extend)
464	    }
465	
466	    /// Selects `index` and seeks there, or, extending, grows the selection
467	    /// from its anchor without a seek.
468	    private func move(to index: Int, extend: Bool) {
469	        if extend {
470	            let anchor = min(max(selectionAnchor ?? caret ?? index, 0), tokenStarts.count - 1)
471	            setSelection(min(anchor, index)...max(anchor, index))
472	            selectionAnchor = anchor
473	            onSelect?(selection)
474	        } else {
475	            select(index...index)
476	            onActivate?(index)
477	        }
478	        if let rect = rects(forToken: index).first, !visibleRect.contains(rect) {
479	            scrollToVisible(rect.insetBy(dx: 0, dy: -24))
480	            layoutViewport()
481	        }
482	    }
483	
484	    override func mouseDown(with event: NSEvent) {
485	        window?.makeFirstResponder(self)
486	        let point = convert(event.locationInWindow, from: nil)
487	        if let paragraph = paragraphIndex(at: point) {
488	            onParagraph?(paragraph)
489	            return
490	        }
491	        if !event.modifierFlags.contains(.shift), let pause = pauseIndex(at: point) {
492	            clickPause(pause)
493	            return
494	        }
495	        guard let index = tokenIndex(at: point) else { return }
496	        if event.modifierFlags.contains(.shift) {
497	            move(to: index, extend: true)
498	        } else {
499	            click(token: index)
500	        }
501	    }
502	
503	    /// A plain click on token `index`: it alone selected, and sought. The
504	    /// mouse's path, which `transcript_view`'s `click` takes too.
505	    func click(token index: Int) {
506	        select(index...index)
507	        onActivate?(index)
508	    }
509	}
