739	        while low < high {
740	            let mid = (low + high) / 2
741	            if timecodeRanges[mid].location <= offset { low = mid + 1 } else { high = mid }
742	        }
743	        guard low > 0 else { return nil }
744	        let range = timecodeRanges[low - 1]
