751	        guard !tokenStarts.isEmpty else { return nil }
752	        let top = visibleRect.minY
753	        let probe = NSPoint(x: Self.inset.width + 1, y: max(top, Self.inset.height) + 1)
754	        guard let offset = characterOffset(at: probe) else { return nil }
755	        let index = token(atOrBefore: offset) ?? 0
756	        if let rect = rects(forToken: index).first, rect.maxY <= top, index + 1 < tokenStarts.count {
757	            return index + 1
758	        }
759	        if paragraphIndex(atOffset: offset) != nil, index + 1 < tokenStarts.count,
760	            tokenStarts[index] < offset
761	        {
762	            return index + 1
763	        }
764	        return index
765	    }
766	
767	    /// Scrolls `index`'s line to the visible top. Laid out twice: the first
768	    /// scroll lands on an estimate for text never laid out, which the
769	    /// viewport layout there settles.
770	    func scrollToToken(_ index: Int) {
771	        for _ in 0..<2 {
772	            guard let rect = rects(forToken: index).first else { return }
773	            scroll(to: rect.minY - 4)
774	        }
775	    }
776	
777	    /// The token nearest in x on the laid-out line above (`up`) or below
778	    /// `index`'s, skipping a timecode line; nil at either end.
779	    func tokenOnAdjacentLine(to index: Int, up: Bool) -> Int? {
780	        guard let rect = rects(forToken: index).first else { return nil }
781	        var y = up ? rect.minY - 1 : rect.maxY + 1
782	        for _ in 0..<4 {
783	            let point = NSPoint(x: rect.midX, y: y)
784	            guard y > 0, y < bounds.maxY, let offset = characterOffset(at: point) else { return nil }
785	            if paragraphIndex(atOffset: offset) == nil, let found = token(atOrBefore: offset),
786	                found != index
787	            {
788	                return found
789	            }
790	            let line = rects(for: NSRange(location: offset, length: 0)).first?.height ?? 16
791	            y += up ? -max(line, 4) : max(line, 4)
792	        }
793	        return nil
794	    }
795	}
