320	    func setHighlight(_ index: Int?, follow: Bool) {
321	        let valid = index.flatMap { tokenStarts.indices.contains($0) ? $0 : nil }
322	        if valid != highlighted {
323	            let old = highlighted
324	            highlighted = valid
325	            if let old { invalidate(old...old) }
326	            if let valid { invalidate(valid...valid) }
327	        }
328	        guard follow, let valid, !personScrolledRecently else { return }
329	        guard let rect = rects(forToken: valid).first else { return }
330	        let shown = visibleRect
331	        let margin = min(shown.height / 4, 48)
332	        if rect.minY < shown.minY + margin / 2 || rect.maxY > shown.maxY - margin {
333	            scroll(to: rect.minY - shown.height / 3)
334	        }
