512	/// `TranscriptView`'s pause tokens (road map "creator-jobs" TX3b, spec §11
513	/// TX-34): the hit test on a pause's text, a click on one — the word
514	/// selection cleared, the pause selected and told through `onSelectPause` —
515	/// and the selected pause's mark, drawn behind the text as a word
516	/// selection's is.
517	extension TranscriptView {
518	
519	    /// The pause whose text is under `point`.
520	    func pauseIndex(at point: NSPoint) -> Int? {
521	        guard !pauseRanges.isEmpty, let offset = characterOffset(at: point) else { return nil }
522	        var low = 0
523	        var high = pauseRanges.count
524	        while low < high {
525	            let mid = (low + high) / 2
526	            if pauseRanges[mid].location <= offset { low = mid + 1 } else { high = mid }
527	        }
528	        for index in [low - 1, low] where pauseRanges.indices.contains(index) {
529	            if rects(for: pauseRanges[index]).contains(where: { $0.insetBy(dx: -2, dy: 0).contains(point) }) {
530	                return index
531	            }
532	        }
533	        return nil
534	    }
535	
536	    /// A click on pause `index`: the words' selection cleared, the pause
537	    /// selected, and told. The mouse's path, which `transcript_view`'s
538	    /// `select_pause` takes too.
539	    func clickPause(_ index: Int) {
540	        guard pauses.indices.contains(index) else { return }
541	        selectionAnchor = nil
542	        setSelection(nil)
543	        setPauseSelection(index)
544	        onSelectPause?(index)
545	    }
546	
547	    /// The selected pause, behind its text.
548	    func drawPauseMark(in dirtyRect: NSRect) {
549	        guard let index = pauseSelection, pauseRanges.indices.contains(index) else { return }
550	        DS.selectionFill.setFill()
551	        for rect in rects(for: pauseRanges[index]) where rect.intersects(dirtyRect) {
552	            rect.fill()
553	        }
554	    }
555	}
