638	/// `TranscriptView`'s geometry: a UTF-16 range's rects, the token or the
639	/// paragraph timecode under a point, the top visible token, and the scroll
640	/// that brings a token to the top. Every rect is in the view's (flipped)
641	/// coordinates: the text container's offset by `TranscriptView.inset`.
642	extension TranscriptView {
643	
644	    /// The text location `offset` UTF-16 units into the document.
645	    func location(_ offset: Int) -> NSTextLocation? {
646	        contentStorage.location(contentStorage.documentRange.location, offsetBy: offset)
647	    }
648	
649	    func offset(of location: NSTextLocation) -> Int {
650	        contentStorage.offset(from: contentStorage.documentRange.location, to: location)
651	    }
652	
653	    func textRange(_ range: NSRange) -> NSTextRange? {
654	        guard let start = location(range.location), let end = location(NSMaxRange(range)) else {
655	            return nil
656	        }
657	        return NSTextRange(location: start, end: end)
658	    }
659	
660	    /// The line-height rects `range` covers, laid out first where needed.
661	    func rects(for range: NSRange) -> [CGRect] {
662	        guard range.location >= 0, let text = textRange(range) else { return [] }
663	        layoutManager.ensureLayout(for: text)
664	        var out: [CGRect] = []
665	        layoutManager.enumerateTextSegments(in: text, type: .highlight, options: []) {
666	            _, frame, _, _ in
667	            out.append(frame.offsetBy(dx: Self.inset.width, dy: Self.inset.height))
668	            return true
669	        }
670	        return out
671	    }
672	
673	    func tokenRange(_ index: Int) -> NSRange {
674	        guard tokenStarts.indices.contains(index) else { return NSRange(location: NSNotFound, length: 0) }
675	        return NSRange(location: tokenStarts[index], length: tokenLengths[index])
676	    }
677	
678	    /// From the first token's start to the last one's end.
679	    func tokenRange(_ tokens: ClosedRange<Int>) -> NSRange {
680	        let low = tokenRange(tokens.lowerBound)
681	        let high = tokenRange(tokens.upperBound)
682	        guard low.location != NSNotFound, high.location != NSNotFound else {
683	            return NSRange(location: NSNotFound, length: 0)
684	        }
685	        return NSRange(location: low.location, length: NSMaxRange(high) - low.location)
686	    }
687	
688	    func rects(forToken index: Int) -> [CGRect] {
689	        let range = tokenRange(index)
690	        return range.location == NSNotFound ? [] : rects(for: range)
691	    }
692	
693	    /// The UTF-16 offset nearest `point`, or nil off the text.
694	    func characterOffset(at point: NSPoint) -> Int? {
695	        let inner = CGPoint(x: point.x - Self.inset.width, y: point.y - Self.inset.height)
696	        guard let fragment = layoutManager.textLayoutFragment(for: inner) else { return nil }
697	        let frame = fragment.layoutFragmentFrame
698	        let start = offset(of: fragment.rangeInElement.location)
699	        let lines = fragment.textLineFragments
700	        guard !lines.isEmpty else { return start }
701	        let local = CGPoint(x: inner.x - frame.minX, y: inner.y - frame.minY)
702	        let line = lines.first { $0.typographicBounds.maxY > local.y } ?? lines[lines.count - 1]
703	        let inLine = CGPoint(x: local.x - line.typographicBounds.minX, y: local.y - line.typographicBounds.minY)
704	        let index = line.characterIndex(for: inLine)
705	        return start + max(index, line.characterRange.location)
706	    }
707	
708	    /// The last token starting at or before `offset`, by binary search.
709	    func token(atOrBefore offset: Int) -> Int? {
710	        var low = 0
711	        var high = tokenStarts.count
712	        while low < high {
713	            let mid = (low + high) / 2
714	            if tokenStarts[mid] <= offset { low = mid + 1 } else { high = mid }
715	        }
716	        return low == 0 ? nil : low - 1
717	    }
718	
719	    /// The token under `point`: the one whose characters (or the space after
720	    /// them) hold the offset there; nil on a timecode or off the text.
721	    func tokenIndex(at point: NSPoint) -> Int? {
722	        guard let offset = characterOffset(at: point), paragraphIndex(atOffset: offset) == nil,
723	            let index = token(atOrBefore: offset)
724	        else { return nil }
725	        let paragraph = model.tokens[index].paragraph
726	        let end = model.paragraphs[paragraph].endToken
727	        let limit = index + 1 < end ? tokenStarts[index + 1] : NSMaxRange(tokenRange(index))
728	        return offset <= limit ? index : nil
729	    }
730	
731	    /// The paragraph whose timecode is under `point`.
732	    func paragraphIndex(at point: NSPoint) -> Int? {
733	        characterOffset(at: point).flatMap { paragraphIndex(atOffset: $0) }
734	    }
735	
736	    private func paragraphIndex(atOffset offset: Int) -> Int? {
737	        var low = 0
738	        var high = timecodeRanges.count
739	        while low < high {
740	            let mid = (low + high) / 2
741	            if timecodeRanges[mid].location <= offset { low = mid + 1 } else { high = mid }
742	        }
743	        guard low > 0 else { return nil }
744	        let range = timecodeRanges[low - 1]
745	        return offset <= NSMaxRange(range) ? low - 1 : nil
746	    }
747	
748	    /// The first token whose line shows at the visible top, else the first
749	    /// token below it.
750	    func topVisibleToken() -> Int? {
751	        guard !tokenStarts.isEmpty else { return nil }
752	        let top = visibleRect.minY
753	        let probe = NSPoint(x: Self.inset.width + 1, y: max(top, Self.inset.height) + 1)
754	        guard let offset = characterOffset(at: probe) else { return nil }
755	        let index = token(atOrBefore: offset) ?? 0
756	        if let rect = rects(forToken: index).first, rect.maxY <= top, index + 1 < tokenStarts.count {
757	            return index + 1
758	        }
759	        if paragraphIndex(atOffset: offset) != nil, index + 1 < tokenStarts.count,
760	            tokenStarts[index] < offset
761	        {
762	            return index + 1
763	        }
764	        return index
765	    }
766	
767	    /// Scrolls `index`'s line to the visible top. Laid out twice: the first
768	    /// scroll lands on an estimate for text never laid out, which the
769	    /// viewport layout there settles.
770	    func scrollToToken(_ index: Int) {
771	        for _ in 0..<2 {
772	            guard let rect = rects(forToken: index).first else { return }
773	            scroll(to: rect.minY - 4)
774	        }
775	    }
776	
777	    /// The token nearest in x on the laid-out line above (`up`) or below
778	    /// `index`'s, skipping a timecode line; nil at either end.
779	    func tokenOnAdjacentLine(to index: Int, up: Bool) -> Int? {
780	        guard let rect = rects(forToken: index).first else { return nil }
781	        var y = up ? rect.minY - 1 : rect.maxY + 1
782	        for _ in 0..<4 {
783	            let point = NSPoint(x: rect.midX, y: y)
784	            guard y > 0, y < bounds.maxY, let offset = characterOffset(at: point) else { return nil }
785	            if paragraphIndex(atOffset: offset) == nil, let found = token(atOrBefore: offset),
786	                found != index
787	            {
788	                return found
789	            }
790	            let line = rects(for: NSRange(location: offset, length: 0)).first?.height ?? 16
791	            y += up ? -max(line, 4) : max(line, 4)
792	        }
793	        return nil
794	    }
795	}
