99	    ) {
100	        let anchor = topVisibleToken().map { index -> (TimelineTranscript.Identity, Ticks, CGFloat) in
101	            let token = model.tokens[index]
102	            let y = (rects(forToken: index).first?.minY ?? visibleRect.minY) - visibleRect.minY
103	            return (token.word.id, token.word.start, y)
