107	        let anchored = selectionAnchor.flatMap { model.tokens.indices.contains($0) ? model.tokens[$0].word.id : nil }
108	        let pausedBetween = pauseSelection.flatMap { index -> (TimelineTranscript.Identity, TimelineTranscript.Identity)? in
109	            let after = self.pauses[index].after
110	            guard after + 1 < model.tokens.count else { return nil }
111	            return (model.tokens[after].word.id, model.tokens[after + 1].word.id)
112	        }
