117	        highlighted = lit.flatMap { model.index(of: $0) }
118	        selection = selected.flatMap { pair in
119	            guard let low = model.index(of: pair.0), let high = model.index(of: pair.1), low <= high
120	            else { return nil }
121	            return low...high
122	        }
123	        pauseSelection = pausedBetween.flatMap { pair in
124	            self.pauses.firstIndex {
