129	        // start: an old index can lie past a shrunk text.
130	        selectionAnchor = selection.map { range in
131	            anchored.flatMap { model.index(of: $0) }.flatMap { range.contains($0) ? $0 : nil } ?? range.lowerBound
132	        }
133	        fitContainer()
134	        layoutViewport()
135	        if let (id, start, offset) = anchor,
136	            let index = model.index(of: id) ?? model.firstIndex(atOrAfter: start),
137	            let rect = rects(forToken: index).first
138	        {
139	            scroll(to: rect.minY - offset)
140	        }
141	        needsDisplay = true
