144	    /// The whole transcript as one attributed string, recording each token's
145	    /// and each timecode's UTF-16 range as it goes. Built as one string and
146	    /// then styled by ranges: an attributed string per word cost a third of
147	    /// a rebuild (TX-S2).
148	    private func text(fps: Fps, frames: Bool) -> NSAttributedString {
149	        let plain = NSMutableString()
150	        var starts: [Int] = []
151	        var lengths: [Int] = []
152	        var timecodes: [NSRange] = []
153	        var faint: [NSRange] = []
154	        var struck: [NSRange] = []
155	        var dim: [(range: NSRange, why: String)] = []
156	        var paused: [NSRange] = []
157	        var pauseAfter: [Int: TranscriptCut.Pause] = [:]
158	        for pause in pauses { pauseAfter[pause.after] = pause }
159	        starts.reserveCapacity(model.tokens.count)
160	        lengths.reserveCapacity(model.tokens.count)
161	        func extend(_ ranges: inout [NSRange], _ range: NSRange) {
162	            if let last = ranges.last, NSMaxRange(last) >= range.location - 1 {
163	                ranges[ranges.count - 1] = NSUnionRange(last, range)
164	            } else {
165	                ranges.append(range)
166	            }
167	        }
168	        for paragraph in model.paragraphs {
169	            let stamp = ReelTime.format(paragraph.start, fps: fps, frames: frames)
170	            timecodes.append(NSRange(location: plain.length, length: (stamp as NSString).length))
171	            plain.append(stamp)
172	            plain.append("\n")
173	            for index in paragraph.firstToken..<paragraph.endToken {
174	                let token = model.tokens[index]
175	                if index > paragraph.firstToken { plain.append(" ") }
176	                if token.collapsedBefore > 0 {
177	                    extend(&faint, NSRange(location: plain.length, length: 2))
178	                    plain.append("⋯ ")
179	                }
180	                let range = NSRange(location: plain.length, length: (token.word.text as NSString).length)
181	                plain.append(token.word.text)
182	                starts.append(range.location)
183	                lengths.append(range.length)
184	                if token.struck {
185	                    extend(&struck, range)
186	                } else if !token.word.editable {
187	                    extend(&faint, range)
188	                }
189	                if !token.word.editable, let why = token.word.why {
190	                    if let last = dim.last, last.why == why, index > paragraph.firstToken,
191	                        !model.tokens[index - 1].word.editable
192	                    {
193	                        dim[dim.count - 1].range = NSUnionRange(last.range, range)
194	                    } else {
195	                        dim.append((range, why))
196	                    }
197	                }
198	                if let pause = pauseAfter[index] {
199	                    let seconds = Double(pause.span.end - pause.span.start) / Double(ReelTime.perSecond)
200	                    let label = String(format: "[%.1f s]", seconds)
201	                    plain.append(" ")
202	                    paused.append(NSRange(location: plain.length, length: (label as NSString).length))
203	                    plain.append(label)
204	                }
205	            }
206	            plain.append("\n")
207	        }
208	        let out = NSMutableAttributedString(string: plain as String, attributes: wordAttributes)
209	        let faintColor = resolved(DS.textFaint)
210	        for range in faint { out.addAttribute(.foregroundColor, value: faintColor, range: range) }
211	        for range in struck {
212	            out.addAttributes(
213	                [.foregroundColor: faintColor, .strikethroughStyle: NSUnderlineStyle.single.rawValue],
214	                range: range)
215	        }
216	        let pauseColor = resolved(DS.textMuted)
217	        for range in paused { out.addAttribute(.foregroundColor, value: pauseColor, range: range) }
218	        let timecode = timecodeAttributes
219	        for range in timecodes {
220	            out.setAttributes(timecode, range: NSRange(location: range.location, length: range.length + 1))
221	        }
222	        tokenStarts = starts
223	        tokenLengths = lengths
224	        timecodeRanges = timecodes
225	        dimRuns = dim
226	        pauseRanges = paused
227	        return out
228	    }
