414	/// The timeline transcript's fill (road map "creator-jobs" TX1, spec §11
415	/// TX-12): each heard media with no cloud transcript and no stored run over
416	/// the whole file is read ONCE, whole, by this Mac's recogniser and kept in
417	/// TR-14's cache (`DeviceTranscriptCache`).
418	///
419	/// **One per document**, keyed by its `recipeKey` (`ProjectDocument.swift`
420	/// takes nothing), and dropped once the document is no longer open
421	/// (`RecipeSource` no longer holds its key, `isOpenForAnalysis`'s test).
422	///
423	/// **Owners** — each tool call while it waits; the Transcript tab from TX2a
424	/// — `want` a list of items, which REPLACES that owner's list; `release`
425	/// withdraws only that owner's want. An item no owner wants is dropped from
426	/// the queue, or, running, cancelled through its `Transcriber.CancelToken`;
427	/// one another owner still wants runs on, and one cancelled and wanted again
428	/// before its run unwound runs afresh. `AnalysisLane`'s shape.
429	///
430	/// **One media at a time**, on one serial `.userInitiated` queue, off main
431	/// (TX-S1: a sibling process's whole-file run left `play_preview` composing
432	/// 300 of 300 frames). The queue takes the wanted items in the order the
433	/// owners gave them (the caller puts the media under the playhead first).
434	/// A run is a whole-file `Transcriber.Job` through
435	/// `TranscriptReader.recognize`, then `Heard(runs:over:)`, then `store` —
436	/// only when it was not cancelled and the file's stamp did not change.
437	final class TranscriptFill: @unchecked Sendable {
438	
439	    /// One media to read whole, with everything the run needs by value.
440	    struct Item: Hashable {
441	        let media: UInt32
442	        let url: URL
443	        let name: String
444	        let duration: Ticks
445	        let stamp: DeviceTranscriptCache.Stamp
446	        let cacheDir: URL
447	        let language: Transcriber.Language
448	        /// The media record, for the stamp's re-read after the run.
449	        let record: MediaSnapshot
450	
451	        func hash(into hasher: inout Hasher) {
452	            hasher.combine(media)
453	            hasher.combine(url)
454	            hasher.combine(language.identifier)
455	        }
456	
457	        /// The whole file as one job: clip 0, from tick 0, at speed 1.
458	        var job: Transcriber.Job {
459	            Transcriber.Job(
460	                clip: 0, media: media, name: name, source: url, sourceIn: 0,
461	                sourceLength: duration, start: 0, duration: duration, speed: 1)
462	        }
463	    }
464	
465	    /// How an item's run ended.
466	    enum Outcome: Equatable {
467	        case stored, failed(String), cancelled
468	    }
469	
470	    /// Main only: the live fills by document key.
471	    private static var fills: [Int: TranscriptFill] = [:]
472	
473	    /// The document's fill, made on first use; every fill whose document has
474	    /// closed is dropped (its queue emptied, its run cancelled). Main.
475	    static func fill(for document: ProjectDocument) -> TranscriptFill {
476	        for (key, fill) in fills where !fill.isAlive {
477	            fill.drop()
478	            fills[key] = nil
479	        }
480	        if let fill = fills[document.recipeKey] { return fill }
481	        let fill = TranscriptFill(key: document.recipeKey)
482	        fills[document.recipeKey] = fill
483	        return fill
484	    }
485	
486	    private let key: Int
487	    private let condition = NSCondition()
488	    private var owners: [Int: [Item]] = [:]
489	    /// What each owner last asked for, kept past its release so `wait` can
490	    /// answer `.cancelled` for what it withdrew.
491	    private var asked: [Int: [Item]] = [:]
492	    private var nextOwner = 0
493	    private var outcomes: [Item: Outcome] = [:]
494	    private var running: (item: Item, token: Transcriber.CancelToken)?
495	    private var fraction: (media: UInt32, fraction: Double)?
496	    private let queue = DispatchQueue(
497	        label: "com.kgalligan.framejob.transcript-fill", qos: .userInitiated)
498	
499	    /// A fill for the document whose `RecipeSource` key is `key`. Internal
500	    /// for `timeline_transcript_probe.swift`; the app makes one through
501	    /// `fill(for:)`.
502	    init(key: Int) {
503	        self.key = key
504	    }
505	
506	    private var isAlive: Bool { RecipeSource.shared.project(for: key) != nil }
507	
508	    /// A fresh owner id. Any thread.
509	    func newOwner() -> Int {
510	        condition.lock()
511	        defer { condition.unlock() }
512	        nextOwner += 1
513	        return nextOwner
514	    }
515	
516	    /// Replaces `owner`'s want with `items`, in the caller's order. An item
517	    /// wanted ANEW after it ended runs again (its caller found the cache
518	    /// missing it). Any thread.
519	    func want(owner: Int, items: [Item]) {
520	        condition.lock()
521	        let earlier = owners[owner] ?? []
522	        for item in items where !earlier.contains(item) && running?.item != item {
523	            outcomes[item] = nil
524	        }
525	        owners[owner] = items.isEmpty ? nil : items
526	        asked[owner] = items
527	        reconcileLocked()
528	        condition.unlock()
529	    }
530	
531	    /// Withdraws `owner`'s want: a run no other owner wants is cancelled.
532	    func release(owner: Int) {
533	        condition.lock()
534	        owners[owner] = nil
535	        reconcileLocked()
536	        condition.unlock()
537	    }
538	
539	    /// Blocks until each item `owner` last asked for has settled — its run
540	    /// stored, failed or was cancelled, or the owner withdrew it (answered
541	    /// `.cancelled`) — and answers each by media. Never on main.
542	    func wait(owner: Int) -> [UInt32: Outcome] {
543	        condition.lock()
544	        defer {
545	            asked[owner] = nil
546	            condition.unlock()
547	        }
548	        while true {
549	            if !isAlive { dropLocked() }
550	            let wanted = owners[owner] ?? []
551	            var answer: [UInt32: Outcome] = [:]
552	            var settled = true
553	            for item in asked[owner] ?? [] {
554	                if let outcome = outcomes[item] {
555	                    answer[item.media] = outcome
556	                } else if !wanted.contains(item) {
557	                    answer[item.media] = .cancelled
558	                } else {
559	                    settled = false
560	                }
561	            }
562	            if settled { return answer }
563	            condition.wait(until: Date().addingTimeInterval(0.05))
564	        }
565	    }
566	
567	    /// The running media and how much of it has been heard, 0…1. Any thread.
568	    func progress() -> (media: UInt32, fraction: Double)? {
569	        condition.lock()
570	        defer { condition.unlock() }
571	        return fraction
572	    }
573	
574	    // MARK: - The queue
575	
576	    private func drop() {
577	        condition.lock()
578	        dropLocked()
579	        condition.unlock()
580	    }
581	
582	    /// The document closed: no owner is left and the run is cancelled.
583	    private func dropLocked() {
584	        owners = [:]
585	        reconcileLocked()
586	    }
587	
588	    /// Cancels a run nobody wants and starts the next wanted item.
589	    private func reconcileLocked() {
590	        let wanted = wantedLocked()
591	        if let running, !wanted.contains(running.item) { running.token.cancel() }
592	        condition.broadcast()
593	        guard running == nil, let next = wanted.first(where: { outcomes[$0] == nil }) else {
594	            return
595	        }
596	        let token = Transcriber.CancelToken()
597	        running = (next, token)
598	        queue.async { [self] in
599	            let outcome = run(next, token: token)
600	            condition.lock()
601	            // A run cancelled for an owner's release that another owner
602	            // wanted before it unwound is no answer to that owner: no
603	            // outcome, so the reconcile below starts it again.
604	            let rewanted = token.isCancelled && wantedLocked().contains(next)
605	            outcomes[next] = outcome == .cancelled && rewanted ? nil : outcome
606	            running = nil
607	            fraction = nil
608	            reconcileLocked()
609	            condition.unlock()
610	        }
611	    }
612	
613	    /// Every owner's items, in owner order then each owner's own, each once.
614	    private func wantedLocked() -> [Item] {
615	        var out: [Item] = []
616	        for owner in owners.keys.sorted() {
617	            for item in owners[owner] ?? [] where !out.contains(item) { out.append(item) }
618	        }
619	        return out
620	    }
621	
622	    /// One whole-file run, off main. A stored run that already covers the
623	    /// file (another caller's) answers `.stored` without recognising.
624	    private func run(_ item: Item, token: Transcriber.CancelToken) -> Outcome {
625	        let job = item.job
626	        if DeviceTranscriptCache.lookup(
627	            job, media: item.media, stamp: item.stamp, in: item.cacheDir) != nil
628	        {
629	            return .stored
630	        }
631	        let seconds = max(ReelTime.seconds(item.duration), 0.001)
632	        let runs: [SpeechEngine.Run]
633	        do {
634	            runs = try TranscriptReader.recognize(
635	                job, language: item.language, cancel: token,
636	                progress: { [weak self] reached in self?.heard(item.media, reached / seconds) })
637	        } catch Transcriber.TranscribeError.cancelled {
638	            return .cancelled
639	        } catch {
640	            return .failed(error.localizedDescription)
641	        }
642	        if token.isCancelled { return .cancelled }
643	        let heard = DeviceTranscriptCache.Heard(runs: runs, over: job)
644	        guard
645	            DeviceTranscriptCache.currentStamp(
646	                item.record, url: item.url, language: item.language.identifier)
647	                == item.stamp
648	        else {
649	            return .failed("“\(item.name)” changed while it was being transcribed. Call again.")
650	        }
651	        guard DeviceTranscriptCache.store(heard, media: item.media, stamp: item.stamp, in: item.cacheDir)
652	        else {
653	            return .failed(
654	                "What was heard in “\(item.name)” could not be kept in the project's cache.")
655	        }
656	        return .stored
657	    }
658	
659	    private func heard(_ media: UInt32, _ share: Double) {
660	        condition.lock()
661	        fraction = (media, min(max(share, 0), 1))
662	        condition.unlock()
663	    }
664	}
