667	/// What this Mac's recogniser heard for `get_transcript` (spec §11 TR-14,
668	/// #332) and for the timeline transcript's whole-file fill
669	/// (`TranscriptFill`, TX-12), cached per media and language so a later call
670	/// inside a stored run answers without recognising again.
671	///
672	/// `cache/device-transcripts/<media id>-<language identifier>.json`: one
673	/// `File` per (media, language), the whole cached state, sorted keys and
674	/// `.atomic`, written only through `CacheLedger.publish` so it never lands
675	/// mid-save. It never shares `cache/transcripts/` with AssemblyAI's files,
676	/// and only `get_transcript` and `get_timeline_transcript` (through
677	/// `TranscriptFill`, TX-12) read it: captions, Remove Filler Words,
678	/// `detect_fillers` and `transcribe_for_fillers` never do (TR-7).
679	///
680	/// - The KEY is `Stamp`: R6-15's four-field source stamp, the language, the
681	///   OS version (the recogniser ships with the OS) and `version`. A file of
682	///   another stamp is a miss, and the next store replaces it whole.
683	/// - A HIT is the first stored run, in file order, whose source span
684	///   contains the span the call would hear. A miss runs exactly that span,
685	///   and the store drops every stored run the new one contains. No gap is
686	///   filled and no words are merged across runs.
687	/// - Words are MEDIA source ticks, so another clip, speed or window over the
688	///   same file reuses them (`TranscriptReader.deviceWords` maps them).
689	enum DeviceTranscriptCache {
690	
691	    /// The folder under the document's cache directory.
692	    static let kind = "device-transcripts"
693	    /// Bumped when what a stored run means changes; a file of another
694	    /// version is a miss.
695	    static let version = 1
696	
697	    /// One recognised word, in MEDIA source ticks.
698	    struct Word: Codable, Equatable {
699	        let text: String
700	        let start: Ticks
701	        let end: Ticks
702	    }
703	
704	    /// One run of the recogniser: the source span it heard and its words.
705	    struct Heard: Codable, Equatable {
706	        let sourceIn: Ticks
707	        let sourceLength: Ticks
708	        let words: [Word]
709	
710	        enum CodingKeys: String, CodingKey {
711	            case sourceIn = "source_in"
712	            case sourceLength = "source_length"
713	            case words
714	        }
715	
716	        init(sourceIn: Ticks, sourceLength: Ticks, words: [Word]) {
717	            self.sourceIn = sourceIn
718	            self.sourceLength = sourceLength
719	            self.words = words
720	        }
721	
722	        /// A run's seconds into the extract as media source ticks:
723	        /// `sourceIn + round(clamp(t × 600000, 0, sourceLength))`, the clamp
724	        /// in `Double` before the conversion. A word with a non-finite time
725	        /// is dropped.
726	        init(runs: [SpeechEngine.Run], over job: Transcriber.Job) {
727	            let length = max(job.sourceLength, 0)
728	            func source(_ t: Double) -> Ticks {
729	                let ticks = min(max(t * Double(ReelTime.perSecond), 0), Double(length))
730	                return job.sourceIn + Ticks(ticks.rounded(.toNearestOrAwayFromZero))
731	            }
732	            self.init(
733	                sourceIn: job.sourceIn, sourceLength: job.sourceLength,
734	                words: runs.compactMap { run in
735	                    guard run.start.isFinite, run.end.isFinite else { return nil }
736	                    return Word(text: run.text, start: source(run.start), end: source(run.end))
737	                })
738	        }
739	
740	        /// Whether this run heard all of [sourceIn, sourceIn + sourceLength).
741	        /// False for a non-positive length, or an end that overflows.
742	        func covers(sourceIn: Ticks, sourceLength: Ticks) -> Bool {
743	            guard sourceLength > 0, self.sourceLength > 0 else { return false }
744	            let (end, over) = sourceIn.addingReportingOverflow(sourceLength)
745	            let (ownEnd, ownOver) = self.sourceIn.addingReportingOverflow(self.sourceLength)
746	            guard !over, !ownOver else { return false }
747	            return self.sourceIn <= sourceIn && end <= ownEnd
748	        }
749	    }
750	
751	    /// The key a file is current for.
752	    struct Stamp: Codable, Equatable {
753	        let source: TranscriptSourceStamp
754	        let language: String
755	        let system: String
756	        let version: Int
757	    }
758	
759	    /// What one file holds: its key and the runs stored under it.
760	    struct File: Codable, Equatable {
761	        let stamp: Stamp
762	        let runs: [Heard]
763	    }
764	
765	    // MARK: - Where it lives
766	
767	    /// `cache/device-transcripts/<media id>-<language>.json`.
768	    static func fileURL(for media: UInt32, language: String, in cacheDir: URL) -> URL {
769	        directory(in: cacheDir).appendingPathComponent("\(media)-\(language).json")
770	    }
771	
772	    private static func directory(in cacheDir: URL) -> URL {
773	        cacheDir.appendingPathComponent(kind, isDirectory: true)
774	    }
775	
776	    // MARK: - Reading
777	
778	    /// The file, or nil when it is missing, unreadable or of another shape.
779	    static func read(for media: UInt32, language: String, in cacheDir: URL) -> File? {
780	        let url = fileURL(for: media, language: language, in: cacheDir)
781	        guard let data = try? Data(contentsOf: url) else { return nil }
782	        return try? JSONDecoder().decode(File.self, from: data)
783	    }
784	
785	    /// The first stored run, in file order, that heard all of `job`'s source
786	    /// span, when the file's stamp is `stamp`; nil otherwise.
787	    static func lookup(
788	        _ job: Transcriber.Job, media: UInt32, stamp: Stamp, in cacheDir: URL
789	    ) -> Heard? {
790	        guard let file = read(for: media, language: stamp.language, in: cacheDir) else {
791	            return nil
792	        }
793	        guard file.stamp == stamp else { return nil }
794	        return file.runs.first { $0.covers(sourceIn: job.sourceIn, sourceLength: job.sourceLength) }
795	    }
796	
797	    // MARK: - Writing
798	
799	    /// `file` with `heard` added: under the same stamp, the stored runs
800	    /// `heard` contains are dropped and `heard` is appended; under another
801	    /// stamp (or none), `heard` alone.
802	    static func merged(_ file: File?, adding heard: Heard, stamp: Stamp) -> File {
803	        guard let file, file.stamp == stamp else { return File(stamp: stamp, runs: [heard]) }
804	        let kept = file.runs.filter { !heard.covers(sourceIn: $0.sourceIn, sourceLength: $0.sourceLength) }
805	        return File(stamp: stamp, runs: kept + [heard])
806	    }
807	
808	    /// Reads, merges and writes the file whole and `.atomic`, inside one
809	    /// `CacheLedger.publish` so no save of the package overlaps it. False
810	    /// for every way it can fail: a run not kept is a run made again.
811	    @discardableResult
